code='''from collections import Counter, defaultdict, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                rr, cc = queue.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        cells.add((nr, nc))
                        queue.append((nr, nc))
            result.append((color, cells))
    return result


def _shape(cells):
    min_r = min(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    max_r = max(r for r, _ in cells)
    max_c = max(c for _, c in cells)
    return tuple(tuple((r, c) in cells
                       for c in range(min_c, max_c + 1))
                 for r in range(min_r, max_r + 1))


def _is_corner_l(cells):
    min_r = min(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    max_r = max(r for r, _ in cells)
    max_c = max(c for _, c in cells)
    height, width = max_r - min_r + 1, max_c - min_c + 1
    if height < 3 or width < 3:
        return False
    local = {(r - min_r, c - min_c) for r, c in cells}
    for edge_r in (0, height - 1):
        for edge_c in (0, width - 1):
            expected = {(r, c) for r in range(height) for c in range(width)
                        if r == edge_r or c == edge_c}
            if local == expected:
                return True
    return False


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    components = _components(grid, background)
    markers = [(color, cells) for color, cells in components if _is_corner_l(cells)]
    if not markers:
        return [row[:] for row in grid]
    marker_color, marker_cells = max(markers, key=lambda item: len(item[1]))

    groups = defaultdict(list)
    for color, cells in components:
        if cells != marker_cells:
            groups[_shape(cells)].append((color, cells))
    pairs = [group for group in groups.values() if len(group) == 2]
    if not pairs:
        return [row[:] for row in grid]

    def pair_distance(group):
        return min(abs(r - mr) + abs(c - mc)
                   for _, cells in group for r, c in cells
                   for mr, mc in marker_cells)

    pair = min(pairs, key=pair_distance)
    center_r, center_c = (h - 1) / 2, (w - 1) / 2

    def center_distance(item):
        _, cells = item
        return sum(abs(r - center_r) + abs(c - center_c) for r, c in cells) / len(cells)

    _, target = min(pair, key=center_distance)
    output = [row[:] for row in grid]
    for r, c in target:
        output[r][c] = marker_color
    return output
